import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testDivide_InfiniteDivisor_ReturnsZERO() {
        // divisor.isInfinite() && !isInfinite() -> returns ZERO
        Complex normal = new Complex(1.0, 1.0);
        Complex infinite = Complex.INF;
        Complex result = normal.divide(infinite);
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }








}

