package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testDivide_FastMath_Path1_AbsC_Less_AbsD() {
        // Case: abs(c) < abs(d)
        // Let c = 1, d = 2. Divisor = 1 + 2i
        // q = 1/2 = 0.5
        // denominator = 1 * 0.5 + 2 = 2.5
        // real = (real % q + imaginary) / denominator
        // imaginary = (imaginary * q - real) / denominator
        Complex dividend = new Complex(4.0, 6.0);
        Complex divisor = new Complex(1.0, 2.0);

        // Manual calculation: (4+6i)/(1+2i) = [(4+6i)(1-2i)] / [1^2 + 2^2] 
        // = [4 - 8i + 6i - 12i^2] / 5 = [4 + 12 - 2i] / 5 = 16/5 - 2i/5 = 3.2 - 0.4i
        Complex result = dividend.divide(divisor);

        assertEquals(3.2, result.getReal(), EPSILON);
        assertEquals(-0.4, result.getImaginary(), EPSILON);
    }




}

