import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;















    @Test
    public void testDivide_FastMath_Path2_AbsC_Greater_Equal_AbsD() {
        // Case: abs(c) >= abs(d)
        // Let c = 2, d = 1. Divisor = 2 + 1i
        Complex dividend = new Complex(4.0, 6.0);
        Complex divisor = new Complex(2.0, 1.0);

        // Manual calculation: (4+6i)/(2+1i) = [(4+6i)(2-i)] / [2^2 + 1^2]
        // = [8 - 4i + 12i - 6i^2] / 5 = [8 + 6 + 8i] / 5 = 14/5 + 8i/5 = 2.8 + 1.6i
        Complex result = dividend.divide(divisor);

        assertEquals(2.8, result.getReal(), EPSILON);
        assertEquals(1.6, result.getImaginary(), EPSILON);
    }


}

