import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

















    @Test
    public void testDivide_EqualityWithOtherObjects() {
        Complex c1 = new Complex(1.0, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex c3 = new Complex(1.0, 2.0);

        assertEquals(c1, c2);
        assertNotEquals(c1, c3);
        assertNotEquals(c1, null);
        assertNotEquals(c1, "not a complex");
    }
}
